<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NoteMind</title><style>
*{box-sizing:border-box}body{margin:0;background:#f7f8fc;color:#162033;font:15px Inter,system-ui,sans-serif}.shell{max-width:1120px;margin:auto;padding:48px 24px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}h1{font-size:29px;margin:0}.tag{background:#e8eaff;color:#4b48b7;border-radius:99px;padding:7px 12px;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:390px 1fr;gap:22px}.card{background:white;border:1px solid #e7e9f2;border-radius:16px;padding:22px;box-shadow:0 8px 28px #2430540b}input,textarea{width:100%;border:1px solid #dce0ec;border-radius:9px;padding:12px;font:inherit;margin:7px 0 14px;outline-color:#665cf6}textarea{resize:vertical;min-height:210px}button{border:0;border-radius:9px;padding:11px 14px;font:inherit;font-weight:700;cursor:pointer;background:linear-gradient(135deg,#655df1,#5147df);color:#fff;box-shadow:0 4px 10px #5c54e82c;transition:transform .18s ease,box-shadow .18s ease,filter .18s ease}button:hover:not(:disabled){transform:translateY(-2px);filter:brightness(1.06);box-shadow:0 8px 18px #5c54e840}button:active:not(:disabled){transform:translateY(0);box-shadow:0 3px 7px #5c54e833}button:focus-visible{outline:3px solid #aaa7ff;outline-offset:2px}button.ghost{background:#f0f2f9;color:#343950;box-shadow:none}button.ghost:hover:not(:disabled){background:#e5e8f5;box-shadow:0 6px 14px #25315d18}.danger{background:#fff0f2!important;color:#c23a55!important;box-shadow:none!important}.danger:hover:not(:disabled){background:#ffe1e6!important;box-shadow:0 6px 14px #c23a5522!important}button:disabled{opacity:.5;cursor:not-allowed}.tools,.actions{display:flex;gap:8px;align-items:center}.tools{margin-bottom:13px}.tools input{margin:0}.note{padding:16px 0;border-bottom:1px solid #edf0f5}.note:last-child{border:0}.note h3{margin:0 0 6px;font-size:16px}.note p{color:#626d82;line-height:1.5;margin:0}.summary{margin:10px 0 0;background:#f0efff;color:#49428c;padding:9px 11px;border-radius:8px;font-size:13px}.meta{color:#8b93a5;font-size:12px;margin-top:8px}.actions{margin-top:13px}.empty{color:#8790a2;text-align:center;padding:45px}.loading{position:fixed;inset:0;z-index:50;display:grid;place-items:center;background:linear-gradient(135deg,#101629a8,#29206491);backdrop-filter:blur(7px);opacity:0;visibility:hidden;transition:opacity .24s ease,visibility .24s}.loading.show{opacity:1;visibility:visible}.loader-card{position:relative;overflow:hidden;width:min(360px,calc(100% - 32px));padding:31px 30px 28px;background:linear-gradient(145deg,#fff,#f7f7ff);border:1px solid #ffffffaa;border-radius:23px;text-align:center;box-shadow:0 28px 75px #0e123866;transform:translateY(12px) scale(.96);transition:transform .24s ease}.loading.show .loader-card{transform:translateY(0) scale(1)}.loader-card:before{content:'';position:absolute;inset:0 0 auto;height:4px;background:linear-gradient(90deg,#5c54e8,#a38bff,#5c54e8);background-size:200% 100%;animation:shimmer 1.4s linear infinite}.ring{--progress:0;position:relative;display:grid;place-items:center;width:104px;height:104px;margin:0 auto 18px;border-radius:50%;background:conic-gradient(#665df1 calc(var(--progress)*1%),#e7e9f6 0);box-shadow:0 0 0 7px #eeedff,0 10px 28px #635bf033}.ring:before{content:'';position:absolute;inset:-8px;border:1px solid #8179ff50;border-radius:50%;animation:spin 2.3s linear infinite}.ring:after{content:'';width:84px;height:84px;background:#fff;border-radius:50%;grid-area:1/1}.percent{z-index:1;grid-area:1/1;font-size:20px;font-weight:800;letter-spacing:-.5px;color:#4c45cf}.loader-card h3{margin:0 0 7px;font-size:18px}.loader-card p{margin:0;color:#747d91;font-size:13px;line-height:1.5}.loader-status{display:flex;justify-content:center;align-items:center;gap:7px;margin-top:13px;color:#625adb;font-size:12px;font-weight:700}.loader-status i{width:7px;height:7px;border-radius:50%;background:#685ff1;box-shadow:0 0 0 0 #685ff180;animation:pulse 1.3s infinite}.bar{height:7px;margin-top:19px;background:#e9ebf5;border-radius:8px;overflow:hidden}.bar i{display:block;width:calc(var(--progress)*1%);height:100%;background:linear-gradient(90deg,#5c54e8,#a28aff);border-radius:inherit;transition:width .25s}@keyframes spin{to{transform:rotate(360deg)}}@keyframes pulse{70%{box-shadow:0 0 0 8px #685ff100}}@keyframes shimmer{to{background-position:200% 0}}@media(max-width:760px){.grid{grid-template-columns:1fr}.shell{padding:24px 16px}}
</style></head><body><main class="shell"><header><div><h1>NoteMind</h1><p style="color:#70798c;margin:7px 0 0">Thoughtful notes, searchable by meaning.</p></div><span class="tag">AI-assisted workspace</span></header><section class="grid"><form class="card" id="form"><h2 id="formTitle" style="margin-top:0">New note</h2><input id="title" placeholder="A clear title" required maxlength="180"><textarea id="content" placeholder="Write what matters..." required></textarea><div class="actions"><button>Save note</button><button class="ghost" type="button" id="cancel" hidden>Cancel</button></div></form><div class="card"><div class="tools"><input id="query" placeholder="Search notes by meaning..."><button type="button" id="search">Search</button><button class="ghost" type="button" id="reset">All</button></div><div id="notes"></div><div class="actions" id="pagination"></div></div></section></main><div class="loading" id="loading" aria-live="polite"><div class="loader-card"><div class="ring" id="ring"><span class="percent" id="percent">0%</span></div><h3 id="loader-title">Processing...</h3><p id="loader-text">Please wait while we complete your request.</p><div class="loader-status"><i></i> Working securely</div><div class="bar" id="bar"><i></i></div></div></div><script>
const api='/api/notes',el=s=>document.querySelector(s);let editing=null,page=1,loaderTimer=null,progress=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function req(url,opt={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...opt}),j=await r.json().catch(()=>({message:'Invalid server response'}));if(!r.ok)throw Error(j.message||Object.values(j.errors||{}).flat()[0]||'Request failed');return j}
function setProgress(value){progress=value;el('#ring').style.setProperty('--progress',value);el('#bar').style.setProperty('--progress',value);el('#percent').textContent=`${value}%`}
function startLoader(title='Processing request',text='Please wait while we complete your request.'){clearInterval(loaderTimer);setProgress(8);el('#loader-title').textContent=title;el('#loader-text').textContent=text;el('#loading').classList.add('show');loaderTimer=setInterval(()=>{if(progress<90)setProgress(Math.min(90,progress+(progress<45?7:3)))},260)}
function stopLoader(){clearInterval(loaderTimer);setProgress(100);setTimeout(()=>el('#loading').classList.remove('show'),180)}
async function run(fn,title,text){startLoader(title,text);try{return await fn()}catch(e){console.error(e);alert(e.message)}finally{stopLoader()}}
function render(items){el('#notes').innerHTML=items.length?items.map(n=>`<article class="note"><h3>${esc(n.title)}</h3><p>${esc(n.content.slice(0,180))}${n.content.length>180?'...':''}</p>${n.summary?`<div class="summary">AI summary: ${esc(n.summary)}</div>`:''}<div class="meta">${new Date(n.created_at).toLocaleDateString()}${n.semantic_score?' | match '+n.semantic_score:''}</div><div class="actions"><button class="ghost" onclick="editNote(${n.id})">Edit</button><button class="ghost" onclick="summarize(${n.id})">Summarize</button><button class="danger" onclick="removeNote(${n.id})">Delete</button></div></article>`).join(''):'<div class="empty">No notes yet. Add your first thought.</div>'}
function pages(m){el('#pagination').innerHTML=m.last_page>1?`<button class="ghost" ${m.page===1?'disabled':''} onclick="go(${m.page-1})">Previous</button><span class="meta">Page ${m.page} of ${m.last_page} | ${m.total} notes</span><button class="ghost" ${m.page===m.last_page?'disabled':''} onclick="go(${m.page+1})">Next</button>`:''}
async function load(){const r=await req(`${api}?limit=10&page=${page}`);render(r.data);pages(r.meta)}
async function search(){const q=el('#query').value.trim();if(!q)return load();const r=await req(`${api}/search?q=${encodeURIComponent(q)}`);render(r.data);el('#pagination').innerHTML='<span class="meta">Semantic search results</span>'}window.go=p=>run(async()=>{page=p;await load()},'Loading notes','Fetching the next page of notes...');
el('#form').onsubmit=e=>{e.preventDefault();run(async()=>{await req(editing?`${api}/${editing}`:api,{method:editing?'PUT':'POST',body:JSON.stringify({title:el('#title').value,content:el('#content').value})});cancel();page=1;await load()},editing?'Updating note':'Saving note','Your note is being saved securely...')};
function cancel(){editing=null;el('#form').reset();el('#formTitle').textContent='New note';el('#cancel').hidden=true}window.editNote=id=>run(async()=>{const n=(await req(`${api}/${id}`)).data;editing=id;el('#title').value=n.title;el('#content').value=n.content;el('#formTitle').textContent='Edit note';el('#cancel').hidden=false;scrollTo({top:0,behavior:'smooth'})},'Opening note','Loading note details...');window.summarize=id=>run(async()=>{const r=await req(`${api}/${id}/summary`,{method:'POST'});if(r.data.provider==='local-fallback')alert(`${r.data.warning}${r.data.provider_status?` (HTTP ${r.data.provider_status})`:''}`);await load()},'Generating AI summary','Reading the note and preparing a concise summary...');window.removeNote=id=>{if(confirm('Delete this note?'))run(async()=>{await req(`${api}/${id}`,{method:'DELETE'});await load()},'Deleting note','Removing this note from your workspace...')};el('#search').onclick=()=>run(search,'Searching notes','Comparing your query with note meanings...');el('#reset').onclick=()=>run(async()=>{el('#query').value='';page=1;await load()},'Loading all notes','Refreshing your notes...');el('#cancel').onclick=cancel;el('#query').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();run(search,'Searching notes','Comparing your query with note meanings...')}};run(load,'Loading notes','Preparing your workspace...');
</script></body></html>
